#include <vector>
#include <cstddef>
#include <limits>
#include <omp.h>

int edgeCount(std::vector<int> const& A, size_t N) {
    // Safely determine how many elements belong to the declared NxN matrix.
    // If A is shorter than N*N, only count the available elements.
    size_t matrixElems = A.size();
    if (N == 0) {
        matrixElems = 0;
    } else if (N <= std::numeric_limits<size_t>::max() / N) {
        const size_t expectedElems = N * N;
        if (expectedElems < matrixElems) {
            matrixElems = expectedElems;
        }
    }

    unsigned long long count = 0ULL;

    #pragma omp parallel for reduction(+:count) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(matrixElems); ++i) {
        count += (A[static_cast<size_t>(i)] != 0) ? 1ULL : 0ULL;
    }

    return static_cast<int>(count);
}
